"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "next",
  "line": [
    [
      [
        "M",
        2.5,
        12
      ],
      [
        "L",
        17.5,
        12
      ]
    ],
    [
      [
        "M",
        12.5,
        4
      ],
      [
        "L",
        20,
        11
      ]
    ],
    [
      [
        "M",
        12.5,
        20
      ],
      [
        "L",
        20,
        13
      ]
    ]
  ]
}

function SignArrowRightWords(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="words" {...props} />
}

export { SignArrowRightWords, shape }
